MAKE CODE: Blink LED without delay
language arduino
// Blink LED on pin 13 every 500ms without using delay().
// Uses millis() to track elapsed time and toggle the LED when 500ms have passed.

const int ledPin = 13;          // Pin connected to the LED
unsigned long previousMillis = 0; // Stores the last time the LED was updated
const long interval = 500;      // Interval at which to blink (milliseconds)
int ledState = LOW;             // Current state of the LED

void setup() {
  pinMode(ledPin, OUTPUT);    // Initialize the LED pin as an output
}

void loop() {
  unsigned long currentMillis = millis(); // Get the current time

  // Check if the interval has passed since the last update
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;       // Save the last time the LED was updated
    ledState = !ledState;                 // Toggle the LED state
    digitalWrite(ledPin, ledState);       // Set the LED to the new state
  }
  // The loop continues without blocking, allowing other code to run
}
END

MAKE CODE: Stepper A4988 800 steps
// Stepper motor on A4988 driver (STEP pin 3, DIR pin 2)
// Moves 800 steps forward and back repeatedly with smooth acceleration.
// Wiring: STEP -> 3, DIR -> 2, ENABLE -> 4 (optional, LOW to enable).
// Ensure Vref is set for your motor's current.
// 800 steps = 2 full turns for a standard 1.8° motor (200 steps/rev) at 1/4 microstepping.
// If using 1/16 microstepping, 800 steps = 0.5 turn. Adjust stepsPerTurn if needed.
#include <AccelStepper.h>

const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 4; // Set to -1 if not using enable pin
const long stepsPerMove = 800; // Number of steps for one direction

// DRIVER mode: STEP and DIR pins
AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  if (enablePin >= 0) {
    pinMode(enablePin, OUTPUT);
    digitalWrite(enablePin, LOW); // Enable driver (LOW is usually active)
  }

  stepper.setMaxSpeed(1000);      // Max speed in steps per second
  stepper.setAcceleration(500);   // Acceleration in steps per second squared
  stepper.moveTo(stepsPerMove);   // Move 800 steps forward
}

void loop() {
  stepper.run(); // Must be called frequently for smooth motion

  // If we reached the target, reverse direction
  if (stepper.distanceToGo() == 0) {
    // Move back the same amount
    stepper.moveTo(-stepsPerMove);
  }
}
END

MAKE CODE: P1AM-100 Start/Stop Seal-in
// P1AM-100: Motor start/stop with seal-in logic.
// Slot 1 (Discrete Input):
//   Channel 1: Start button (Normally Open)
//   Channel 2: Stop button (Normally Closed)
// Slot 2 (Discrete Output):
//   Channel 1: Motor Contactor
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs
  // Start is NO: true when pressed
  bool startPressed = P1.readDiscrete(inSlot, 1);
  // Stop is NC: true when NOT pressed (circuit closed)
  bool stopPressed = !P1.readDiscrete(inSlot, 2);

  // Seal-in logic:
  // Turn on if Start is pressed OR already running.
  // Turn off if Stop is pressed (stopPressed is false) OR Stop is released (stopPressed is true means circuit open? No, Stop NC means input is HIGH when not pressed).
  // Correction: Stop NC means the input pin reads HIGH (1) when the button is NOT pressed.
  // If the button is pressed, the circuit opens, input reads LOW (0).
  // So, we want the motor to run if (Start OR Running) AND (Stop is NOT pressed).
  // Stop is NOT pressed means P1.readDiscrete(inSlot, 2) is true (1).

  bool stopOk = P1.readDiscrete(inSlot, 2); // True if Stop is not pressed (NC closed)

  motorRunning = (startPressed || motorRunning) && stopOk;

  // Write output
  P1.writeDiscrete(motorRunning, outSlot, 1);
}
END

MAKE CODE: Average temperature from CSV
python
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 avg_temp.py readings.csv")
        return

    path = sys.argv[1]
    temps = []

    try:
        with open(path, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                try:
                    # Extract the 'temp' column and convert to float
                    val = float(row['temp'])
                    temps.append(val)
                except (KeyError, ValueError):
                    # Skip rows missing 'temp' or with non-numeric values
                    continue

        if not temps:
            print("No valid temperature data found.")
            return

        avg = sum(temps) / len(temps)
        print(f"Average temperature: {avg:.2f}")

    except FileNotFoundError:
        print(f"Error: File '{path}' not found.")
    except Exception as e:
        print(f"Error reading file: {e}")

if __name__ == "__main__":
    main()
END

