MAKE CODE: Tank Fill Control
language st
// Tank Fill Control in Structured Text
// Inputs:
//   LowFloat  - Switch that closes (true) when water is low
//   HighFloat - Switch that closes (true) when water is high
// Output:
//   FillValve - Valve to open when filling
// Logic:
//   Open FillValve when LowFloat is true.
//   Close FillValve when HighFloat is true.
//   If both are true (tank full), close the valve.

PROGRAM TankFill
VAR
    LowFloat : BOOL;   // Input: Low level switch
    HighFloat : BOOL;  // Input: High level switch
    FillValve : BOOL;  // Output: Fill valve
END_VAR

// Control Logic
// If HighFloat is active, close the valve (safety priority).
// Else if LowFloat is active, open the valve.
// Otherwise, keep the valve closed.
IF HighFloat THEN
    FillValve := FALSE;
ELSIF LowFloat THEN
    FillValve := TRUE;
ELSE
    FillValve := FALSE;
END_IF

END_PROGRAM
END
